// Smoke + parity test for the flat C-API: load -> classify PCM -> top tag.
// argv[1] = model gguf, argv[2] = baseline gguf
#include "ced_capi.h"
#include "parity.hpp"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

int main(int argc, char** argv) {
    std::string model = argc > 1 ? argv[1] : "models/ced-base-f32.gguf";
    std::string baseline = argc > 2 ? argv[2] : "tests/fixtures/ced-base.baseline.gguf";

    ced_ctx* ctx = ced_capi_load(model.c_str());
    if (!ctx) {
        std::fprintf(stderr, "FAIL: load: %s\n", ced_capi_last_error(nullptr));
        return 1;
    }
    bool ok = true;
    ok &= (ced_capi_abi_version() == 1);
    ok &= (ced_capi_num_classes(ctx) == 527);
    ok &= (ced_capi_sample_rate(ctx) == 16000);

    std::vector<float> wav, refp;
    std::vector<int64_t> shp;
    if (!cedtest::load_baseline(baseline, "audio_waveform", wav, shp) ||
        !cedtest::load_baseline(baseline, "probs", refp, shp)) {
        ced_capi_free(ctx);
        return 1;
    }
    int ref_argmax = 0;
    for (int i = 1; i < (int)refp.size(); ++i)
        if (refp[i] > refp[ref_argmax]) ref_argmax = i;

    // struct-array path
    ced_tag tags[5];
    int n = ced_capi_classify_pcm(ctx, wav.data(), (int)wav.size(), 16000, tags, 5);
    if (n <= 0) {
        std::fprintf(stderr, "FAIL: classify_pcm: %s\n", ced_capi_last_error(ctx));
        ced_capi_free(ctx);
        return 1;
    }
    std::fprintf(stderr, "top tag: [%d] %s score=%.4f (ref argmax=%d)\n", tags[0].index,
                 tags[0].label, tags[0].score, ref_argmax);
    ok &= (tags[0].index == ref_argmax);

    // JSON path
    char* json = ced_capi_classify_pcm_json(ctx, wav.data(), (int)wav.size(), 16000, 3);
    if (!json) { ok = false; } else {
        std::fprintf(stderr, "json: %s\n", json);
        ok &= (std::strstr(json, "\"label\"") != nullptr);
        ced_capi_free_string(json);
    }

    // all-scores path: same numbers as the sorted top-k path, in index order
    {
        const int nc = ced_capi_num_classes(ctx);
        std::vector<float> all(nc, -1.0f);
        int w = ced_capi_classify_pcm_probs(ctx, wav.data(), (int)wav.size(), 16000,
                                            all.data(), nc);
        ok &= (w == nc);
        std::vector<ced_tag> sorted(nc);
        int ns = ced_capi_classify_pcm(ctx, wav.data(), (int)wav.size(), 16000,
                                       sorted.data(), nc);
        ok &= (ns == nc);
        for (int i = 0; i < ns; ++i) ok &= (all[sorted[i].index] == sorted[i].score);
        // short buffer: only the first n_out classes
        float three[3];
        ok &= (ced_capi_classify_pcm_probs(ctx, wav.data(), (int)wav.size(), 16000,
                                           three, 3) == 3);
        ok &= (three[0] == all[0] && three[2] == all[2]);
        // errors
        ok &= (ced_capi_classify_pcm_probs(ctx, nullptr, 10, 16000, three, 3) == -1);
        ok &= (ced_capi_classify_pcm_probs(ctx, wav.data(), (int)wav.size(), 16000,
                                           nullptr, 3) == -1);
        std::fprintf(stderr, "classify_pcm_probs: %s\n", ok ? "ok" : "FAIL");
    }

    ced_capi_free(ctx);
    std::fprintf(stderr, "%s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}

#ifndef CED_CAPI_H
#define CED_CAPI_H

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

// Flat C-API for ced.cpp — designed for dlopen / cgo / purego (LocalAI).
//
// All functions are extern "C" and never let a C++ exception cross the
// boundary. The model is loaded ONCE into an opaque `ced_ctx` and reused across
// classify calls (a single ctx is single-threaded: serialize calls or use one
// ctx per worker). Returned strings are malloc'd UTF-8 owned by the caller and
// released with ced_capi_free_string.
//
// The per-PCM entry points (ced_capi_classify_pcm*) take an arbitrary-length
// mono buffer, so a realtime/websocket consumer can call them on a sliding
// window for live recognition.

typedef struct ced_ctx ced_ctx;

// ABI version. Bump on any breaking change below. v1: initial classify API.
// The *_load_from_memory* functions were added later and do not change the version.
int ced_capi_abi_version(void);

// Load a GGUF model. Returns an owning context or NULL on failure (on failure,
// ced_capi_last_error(NULL) holds the message). Release with ced_capi_free.
ced_ctx* ced_capi_load(const char* gguf_path);

// Load a GGUF model from memory instead of a file. `data` points to the bytes of
// a complete GGUF file of `size` bytes. Nothing is read from disk and no
// temporary file is made, on any platform.
//
// Ownership: the buffer is only read during this call. The loader copies the
// tensor data into its own memory, so the caller may free or overwrite `data`
// as soon as the call returns, whatever the result. While the call runs, the
// memory use peaks at about the buffer size plus the model size.
//
// A truncated or corrupt buffer is rejected: the call returns NULL and
// ced_capi_last_error(NULL) holds the reason. It never reads outside
// [data, data + size). Same threading rules as ced_capi_load: the error string
// is thread-local and loads from several threads at once are safe.
// Release the context with ced_capi_free.
ced_ctx* ced_capi_load_from_memory(const void* data, size_t size);

// As ced_capi_load_from_memory, for a model stored inside a larger GGUF such as
// a bundle. Every metadata key and every tensor name of the model is stored as
// `<prefix><name>` (for example prefix "ced." gives "ced.ced.depth" and
// "ced.encoder.init_bn.weight"). Only the tensors under the prefix are copied,
// so the caller can pass the bytes of the whole bundle and no standalone copy of
// the component is needed. `prefix` must not be NULL or empty (use
// ced_capi_load_from_memory for a standalone model). Same ownership rule: the
// buffer may be freed after the call. NULL, with the reason in
// ced_capi_last_error(NULL), if the prefix matches no tensors.
ced_ctx* ced_capi_load_from_memory_prefixed(const void* data, size_t size, const char* prefix);

// Free a context from ced_capi_load. Safe on NULL.
void ced_capi_free(ced_ctx* ctx);

// Last error string. Pass the ctx whose call failed, or NULL for load-time
// errors. Never NULL; "" when there is no error. Borrowed (do not free).
const char* ced_capi_last_error(const ced_ctx* ctx);

// Model introspection.
int         ced_capi_num_classes(const ced_ctx* ctx);   // e.g. 527
const char* ced_capi_label(const ced_ctx* ctx, int index);  // borrowed, NULL if oob
int         ced_capi_sample_rate(const ced_ctx* ctx);   // e.g. 16000

// Classify mono float PCM (`samples`, length `n_samples`, range ~[-1,1]). If
// `sample_rate` differs from the model rate the audio is linearly resampled.
// Clips longer than the model window are chunked and averaged.
//
// Returns a malloc'd JSON array of the top-k tags, score-descending:
//   [{"index":23,"label":"Baby cry, infant cry","score":0.87}, ...]
// `top_k <= 0` returns all classes. Free with ced_capi_free_string. NULL on
// error (see ced_capi_last_error).
char* ced_capi_classify_pcm_json(ced_ctx* ctx, const float* samples, int n_samples,
                                 int sample_rate, int top_k);

// As above, reading a WAV file (any sample rate / channel count; downmixed to
// mono and resampled to the model rate).
char* ced_capi_classify_path_json(ced_ctx* ctx, const char* wav_path, int top_k);

// Struct-array variant (no JSON / no allocation of strings to free). Fills up to
// `max_tags` top tags into `out` (score-descending) and returns the count
// written, or -1 on error. `label` pointers are borrowed from the context and
// valid until ced_capi_free.
typedef struct {
    int         index;
    float       score;
    const char* label;
} ced_tag;

int ced_capi_classify_pcm(ced_ctx* ctx, const float* samples, int n_samples, int sample_rate,
                          ced_tag* out, int max_tags);

// All class scores for mono float PCM, in class-index order (no sorting, no
// allocation). Writes min(n_out, ced_capi_num_classes(ctx)) floats into `out`
// and returns that count, or -1 on error (see ced_capi_last_error). Resamples
// like ced_capi_classify_pcm when `sample_rate` differs from the model rate.
int ced_capi_classify_pcm_probs(ced_ctx* ctx, const float* samples, int n_samples,
                                int sample_rate, float* out, int n_out);

// Free a string returned by a *_json function. Safe on NULL.
void ced_capi_free_string(char* s);

#ifdef __cplusplus
}
#endif
#endif  // CED_CAPI_H

#include "ced_capi.h"

#include "audio_io.hpp"
#include "ced.hpp"

#include <algorithm>
#include <cstdlib>
#include <exception>
#include <new>
#include <cstring>
#include <numeric>
#include <string>
#include <vector>

namespace {

struct CedContext {
    ced::Ced model;
    std::string last_error;
};

// Thread-local error for load-time failures (no context to attach to yet).
thread_local std::string g_load_error;

char* dup_cstr(const std::string& s) {
    char* p = (char*)std::malloc(s.size() + 1);
    if (p) std::memcpy(p, s.c_str(), s.size() + 1);
    return p;
}

void json_escape(const std::string& in, std::string& out) {
    for (char ch : in) {
        switch (ch) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\t': out += "\\t"; break;
            case '\r': out += "\\r"; break;
            default: out += ch;
        }
    }
}

std::vector<int> topk_indices(const std::vector<float>& v, int k) {
    const int n = (int)v.size();
    if (k <= 0 || k > n) k = n;
    std::vector<int> idx(n);
    std::iota(idx.begin(), idx.end(), 0);
    std::partial_sort(idx.begin(), idx.begin() + k, idx.end(),
                      [&](int a, int b) { return v[a] > v[b]; });
    idx.resize(k);
    return idx;
}

// Run classify, resampling if needed. Returns false + sets ctx->last_error.
bool do_classify(CedContext* c, const float* samples, int n_samples, int sample_rate,
                 std::vector<float>& probs) {
    const int model_sr = (int)c->model.config().sample_rate;
    std::vector<float> wav(samples, samples + (n_samples > 0 ? n_samples : 0));
    if (sample_rate > 0 && sample_rate != model_sr)
        wav = ced::resample_linear(wav, sample_rate, model_sr);
    std::vector<float> logits;
    if (!c->model.classify(wav, logits, probs)) {
        c->last_error = "classify failed (audio too short or graph error)";
        return false;
    }
    c->last_error.clear();
    return true;
}

std::string tags_json(CedContext* c, const std::vector<float>& probs, int top_k) {
    const auto& labels = c->model.config().labels;
    std::vector<int> idx = topk_indices(probs, top_k);
    std::string out = "[";
    for (size_t i = 0; i < idx.size(); ++i) {
        int id = idx[i];
        std::string esc;
        if (id < (int)labels.size()) json_escape(labels[id], esc);
        char num[64];
        std::snprintf(num, sizeof(num), "{\"index\":%d,\"score\":%.6f,\"label\":\"", id,
                      probs[id]);
        out += num;
        out += esc;
        out += "\"}";
        if (i + 1 < idx.size()) out += ",";
    }
    out += "]";
    return out;
}

}  // namespace

extern "C" {

int ced_capi_abi_version(void) { return 1; }

ced_ctx* ced_capi_load(const char* gguf_path) {
    if (!gguf_path) {
        g_load_error = "null model path";
        return nullptr;
    }
    auto* c = new (std::nothrow) CedContext();
    if (!c) {
        g_load_error = "out of memory";
        return nullptr;
    }
    if (!c->model.load(gguf_path)) {
        g_load_error = std::string("failed to load model: ") + gguf_path;
        delete c;
        return nullptr;
    }
    g_load_error.clear();
    return reinterpret_cast<ced_ctx*>(c);
}

static ced_ctx* load_memory_impl(const void* data, size_t size, const std::string& prefix) {
    if (!data || size == 0) {
        g_load_error = "empty model buffer";
        return nullptr;
    }
    auto* c = new (std::nothrow) CedContext();
    if (!c) {
        g_load_error = "out of memory";
        return nullptr;
    }
    try {
        if (!c->model.load_from_memory(data, size, prefix)) {
            const std::string& why = c->model.load_error();
            g_load_error = "failed to load model from memory: " +
                           why;
            delete c;
            return nullptr;
        }
    } catch (const std::exception& e) {
        g_load_error = std::string("failed to load model from memory: ") + e.what();
        delete c;
        return nullptr;
    }
    g_load_error.clear();
    return reinterpret_cast<ced_ctx*>(c);
}

ced_ctx* ced_capi_load_from_memory(const void* data, size_t size) {
    return load_memory_impl(data, size, std::string());
}

ced_ctx* ced_capi_load_from_memory_prefixed(const void* data, size_t size, const char* prefix) {
    if (!prefix || !*prefix) {
        g_load_error = "null or empty prefix";
        return nullptr;
    }
    return load_memory_impl(data, size, prefix);
}

void ced_capi_free(ced_ctx* ctx) { delete reinterpret_cast<CedContext*>(ctx); }

const char* ced_capi_last_error(const ced_ctx* ctx) {
    if (!ctx) return g_load_error.c_str();
    return reinterpret_cast<const CedContext*>(ctx)->last_error.c_str();
}

int ced_capi_num_classes(const ced_ctx* ctx) {
    if (!ctx) return 0;
    return (int)reinterpret_cast<const CedContext*>(ctx)->model.config().labels.size();
}

const char* ced_capi_label(const ced_ctx* ctx, int index) {
    if (!ctx) return nullptr;
    const auto& labels = reinterpret_cast<const CedContext*>(ctx)->model.config().labels;
    if (index < 0 || index >= (int)labels.size()) return nullptr;
    return labels[index].c_str();
}

int ced_capi_sample_rate(const ced_ctx* ctx) {
    if (!ctx) return 0;
    return (int)reinterpret_cast<const CedContext*>(ctx)->model.config().sample_rate;
}

char* ced_capi_classify_pcm_json(ced_ctx* ctx, const float* samples, int n_samples,
                                 int sample_rate, int top_k) {
    auto* c = reinterpret_cast<CedContext*>(ctx);
    if (!c || !samples) return nullptr;
    std::vector<float> probs;
    if (!do_classify(c, samples, n_samples, sample_rate, probs)) return nullptr;
    return dup_cstr(tags_json(c, probs, top_k));
}

char* ced_capi_classify_path_json(ced_ctx* ctx, const char* wav_path, int top_k) {
    auto* c = reinterpret_cast<CedContext*>(ctx);
    if (!c || !wav_path) return nullptr;
    ced::Audio a;
    if (!ced::load_audio_mono(wav_path, a, (int)c->model.config().sample_rate)) {
        c->last_error = std::string("failed to read wav: ") + wav_path;
        return nullptr;
    }
    std::vector<float> probs;
    if (!do_classify(c, a.samples.data(), (int)a.samples.size(), a.sample_rate, probs))
        return nullptr;
    return dup_cstr(tags_json(c, probs, top_k));
}

int ced_capi_classify_pcm(ced_ctx* ctx, const float* samples, int n_samples, int sample_rate,
                          ced_tag* out, int max_tags) {
    auto* c = reinterpret_cast<CedContext*>(ctx);
    if (!c || !samples || !out || max_tags <= 0) return -1;
    std::vector<float> probs;
    if (!do_classify(c, samples, n_samples, sample_rate, probs)) return -1;
    const auto& labels = c->model.config().labels;
    std::vector<int> idx = topk_indices(probs, max_tags);
    int n = (int)idx.size();
    for (int i = 0; i < n; ++i) {
        out[i].index = idx[i];
        out[i].score = probs[idx[i]];
        out[i].label = idx[i] < (int)labels.size() ? labels[idx[i]].c_str() : "";
    }
    return n;
}

int ced_capi_classify_pcm_probs(ced_ctx* ctx, const float* samples, int n_samples,
                                int sample_rate, float* out, int n_out) {
    auto* c = reinterpret_cast<CedContext*>(ctx);
    if (!c || !samples || !out || n_out <= 0) return -1;
    std::vector<float> probs;
    if (!do_classify(c, samples, n_samples, sample_rate, probs)) return -1;
    const int n = std::min(n_out, (int)probs.size());
    std::memcpy(out, probs.data(), (size_t)n * sizeof(float));
    return n;
}

void ced_capi_free_string(char* s) { std::free(s); }

}  // extern "C"

#pragma once
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

struct ggml_tensor;
struct ggml_context;
struct gguf_context;
struct ggml_backend_buffer;
typedef struct ggml_backend_buffer* ggml_backend_buffer_t;

namespace ced {

class Backend;

// All config is read from the GGUF (metadata-driven); nothing is hardcoded.
struct CedConfig {
    std::string arch;
    // transformer
    uint32_t embed_dim = 0, depth = 0, num_heads = 0, outputdim = 0;
    float    mlp_ratio = 4.0f;
    bool     qkv_bias = true;
    uint32_t patch_size = 16, patch_stride = 16, target_length = 0;
    std::string pooling = "mean";
    float    ln_eps_encoder = 1e-6f, ln_eps_head = 1e-5f, bn_eps = 1e-5f;
    // mel frontend
    uint32_t sample_rate = 16000, n_mels = 0, n_fft = 0, win_size = 0, hop_size = 0, n_freqs = 0;
    float    f_min = 0.0f, f_max = 8000.0f;
    bool     center = true;
    float    a2db_multiplier = 10.0f, a2db_amin = 1e-10f, a2db_top_db = 120.0f, a2db_ref = 1.0f;
    // labels (AudioSet ontology, index order)
    std::vector<std::string> labels;
};

class ModelLoader {
public:
    ModelLoader() = default;
    ~ModelLoader();
    bool load(const std::string& path);
    // Load from a GGUF held in memory. Nothing is read from disk, and `data` is
    // only read during the call: the tensor data is copied into the loader's own
    // buffers, so the caller may free or reuse `data` afterwards.
    //
    // A non-empty `prefix` selects one model inside a larger GGUF (a bundle):
    // every metadata key and tensor name of the model is stored as
    // `<prefix><name>`. Only the tensors under the prefix are copied, and they
    // are seen under their unprefixed names.
    bool load_from_memory(const void* data, size_t size, const std::string& prefix = "");
    // Why the last load failed ("" if it did not).
    const std::string& error() const { return err_; }
    const CedConfig& config() const { return cfg_; }
    ggml_tensor* tensor(const std::string& name) const;  // nullptr if absent
    // Make every weight usable as a graph leaf on `backend`. CPU: zero-copy
    // (wraps the ctx mem buffer). GPU: one upload into a device buffer at load,
    // after which the host copy is released; tensor() then returns the device
    // tensors. Idempotent.
    bool realize_weights(const Backend& backend);
    // Host f32 copy of a small tensor the CPU side reads directly (mel window,
    // mel filterbank, init_bn stats). Valid after realize_weights, on any
    // device. nullptr if absent or not f32.
    const float* host_f32(const std::string& name) const;

private:
    bool read_model(const std::string& prefix);  // shared by every load path

    CedConfig cfg_;
    std::string err_;
    gguf_context* gguf_ = nullptr;
    ggml_context* ctx_ = nullptr;
    ggml_context* dev_ctx_ = nullptr;          // no_alloc mirror of ctx_ (GPU path)
    ggml_backend_buffer_t weights_buf_ = nullptr;
    std::unordered_map<std::string, ggml_tensor*> tensors_;
    std::unordered_map<std::string, std::vector<float>> host_;
};

}  // namespace ced

#include "model_loader.hpp"

#include "ced_runner.hpp"
#include "gguf_check.hpp"

#include "ggml-backend.h"
#include "ggml-cpu.h"
#include "ggml.h"
#include "gguf.h"

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

namespace ced {

namespace {

// Reads typed keys from a gguf_context. Every accessor checks the stored type
// first: ggml aborts on a type or array/scalar mismatch, and a model that comes
// from a caller's memory buffer must not be able to do that. A mismatch is
// remembered in `bad` and reported once by the loader.
struct Kv {
    gguf_context* g;
    std::string prefix;
    std::string bad;

    int64_t find(const char* k, gguf_type want, bool array = false) {
        int64_t id = gguf_find_key(g, (prefix + k).c_str());
        if (id < 0) return -1;
        const bool is_arr = gguf_get_kv_type(g, id) == GGUF_TYPE_ARRAY;
        const gguf_type t = is_arr ? gguf_get_arr_type(g, id) : gguf_get_kv_type(g, id);
        if (is_arr != array || t != want) {
            if (bad.empty()) bad = "metadata key '" + prefix + k + "' has an unexpected type";
            return -1;
        }
        return id;
    }
    uint32_t u32(const char* k, uint32_t d = 0) {
        int64_t id = find(k, GGUF_TYPE_UINT32);
        return id < 0 ? d : gguf_get_val_u32(g, id);
    }
    float f32(const char* k, float d = 0) {
        int64_t id = find(k, GGUF_TYPE_FLOAT32);
        return id < 0 ? d : gguf_get_val_f32(g, id);
    }
    bool boolean(const char* k, bool d = false) {
        int64_t id = find(k, GGUF_TYPE_BOOL);
        return id < 0 ? d : gguf_get_val_bool(g, id);
    }
    std::string str(const char* k, const char* d = "") {
        int64_t id = find(k, GGUF_TYPE_STRING);
        return id < 0 ? std::string(d) : std::string(gguf_get_val_str(g, id));
    }
};

}  // namespace

ModelLoader::~ModelLoader() {
    if (weights_buf_) ggml_backend_buffer_free(weights_buf_);
    if (gguf_) gguf_free(gguf_);
    if (dev_ctx_) ggml_free(dev_ctx_);
    if (ctx_) ggml_free(ctx_);
}

// Tensors read on the host (the mel frontend and the init_bn fold), kept as
// host copies so they stay readable once the weights move to a device.
static bool host_side(const std::string& n) {
    return n.rfind("ced.mel_", 0) == 0 || n.rfind("encoder.init_bn.", 0) == 0;
}

bool ModelLoader::realize_weights(const Backend& backend) {
    if (weights_buf_) return true;  // idempotent
    if (!ctx_ || !backend.ok()) return false;

    for (auto& kv : tensors_) {
        ggml_tensor* t = kv.second;
        if (!host_side(kv.first) || t->type != GGML_TYPE_F32) continue;
        const float* p = (const float*)t->data;
        host_[kv.first].assign(p, p + ggml_nelements(t));
    }

    if (backend.is_cpu()) {
        // The GGUF was loaded no_alloc=false, so every tensor's data lives in
        // one contiguous ctx mem buffer. Wrap that exact memory as a CPU
        // backend buffer (zero-copy) and point every tensor's ->buffer at it;
        // graphs then reference the loader's tensors directly as leaves.
        void* base = ggml_get_mem_buffer(ctx_);
        size_t size = ggml_get_mem_size(ctx_);
        weights_buf_ = ggml_backend_cpu_buffer_from_ptr(base, size);
        if (!weights_buf_) return false;
        for (auto& kv : tensors_) kv.second->buffer = weights_buf_;
        return true;
    }

    // Device: mirror every tensor into a no_alloc context, allocate them all in
    // one device buffer, upload once, then drop the host copy.
    struct ggml_init_params ip { ggml_tensor_overhead() * (tensors_.size() + 1), nullptr,
                                 /*no_alloc=*/true };
    dev_ctx_ = ggml_init(ip);
    if (!dev_ctx_) return false;
    std::unordered_map<std::string, ggml_tensor*> dev;
    for (auto& kv : tensors_) {
        ggml_tensor* d = ggml_dup_tensor(dev_ctx_, kv.second);
        ggml_set_name(d, kv.first.c_str());
        dev[kv.first] = d;
    }
    weights_buf_ = ggml_backend_alloc_ctx_tensors(dev_ctx_, backend.handle());
    if (!weights_buf_) {
        std::fprintf(stderr, "ced: device weight allocation failed\n");
        return false;
    }
    ggml_backend_buffer_set_usage(weights_buf_, GGML_BACKEND_BUFFER_USAGE_WEIGHTS);
    for (auto& kv : tensors_)
        ggml_backend_tensor_set(dev[kv.first], kv.second->data, 0, ggml_nbytes(kv.second));
    tensors_ = std::move(dev);
    ggml_free(ctx_);
    ctx_ = nullptr;
    return true;
}

const float* ModelLoader::host_f32(const std::string& n) const {
    auto it = host_.find(n);
    return it == host_.end() ? nullptr : it->second.data();
}

bool ModelLoader::load(const std::string& path) {
    err_.clear();
    struct gguf_init_params p { /*no_alloc=*/false, /*ctx=*/&ctx_ };
    gguf_ = gguf_init_from_file(path.c_str(), p);
    if (!gguf_) {
        err_ = "cannot open or parse GGUF file: " + path;
        std::fprintf(stderr, "ced: gguf open failed: %s\n", path.c_str());
        return false;
    }
    return read_model("");
}

bool ModelLoader::load_from_memory(const void* data, size_t size, const std::string& prefix) {
    err_.clear();
    if (!data || size == 0) {
        err_ = "empty model buffer";
        return false;
    }
    if (!gguf_precheck(data, size, &err_)) return false;
    if (prefix.empty()) {
        // ggml copies the tensor data into ctx_; `data` is not used after this call.
        struct gguf_init_params p { /*no_alloc=*/false, /*ctx=*/&ctx_ };
        gguf_ = gguf_init_from_buffer(data, size, p);
        if (!gguf_) {
            err_ = "model buffer is not a valid GGUF file (truncated or corrupt)";
            return false;
        }
        return read_model("");
    }

    // Prefixed view: parse only the header and tensor table, then copy just the
    // tensors under `prefix` into a context of our own, under their stripped names.
    ggml_context* meta = nullptr;
    struct gguf_init_params p { /*no_alloc=*/true, /*ctx=*/&meta };
    gguf_ = gguf_init_from_buffer(data, size, p);
    if (!gguf_) {
        err_ = "model buffer is not a valid GGUF file (truncated or corrupt)";
        return false;
    }
    struct MetaGuard {
        ggml_context* c;
        ~MetaGuard() { if (c) ggml_free(c); }
    } guard{meta};

    const uint64_t data_off = gguf_get_data_offset(gguf_);
    if (data_off > size) {
        err_ = "model buffer is truncated (tensor data starts past the end)";
        return false;
    }
    const uint64_t avail = size - data_off;
    const int64_t nt = gguf_get_n_tensors(gguf_);
    std::vector<int64_t> ids;
    size_t need = 0;
    for (int64_t i = 0; i < nt; ++i) {
        const char* nm = gguf_get_tensor_name(gguf_, i);
        if (std::strncmp(nm, prefix.c_str(), prefix.size()) != 0) continue;
        const uint64_t off = gguf_get_tensor_offset(gguf_, i);
        const uint64_t nb = gguf_get_tensor_size(gguf_, i);
        if (off > avail || nb > avail - off) {
            err_ = std::string("model buffer is truncated (tensor ") + nm + " is out of range)";
            return false;
        }
        ggml_tensor* src = ggml_get_tensor(meta, nm);
        if (!src || ggml_nbytes(src) != nb) {
            err_ = std::string("tensor table is inconsistent for ") + nm;
            return false;
        }
        need += GGML_PAD((size_t)nb, GGML_MEM_ALIGN) + GGML_MEM_ALIGN + ggml_tensor_overhead();
        ids.push_back(i);
    }
    if (ids.empty()) {
        err_ = "no tensors under prefix '" + prefix + "' in the model buffer";
        return false;
    }
    struct ggml_init_params ip { need + 4096, nullptr, /*no_alloc=*/false };
    ctx_ = ggml_init(ip);
    if (!ctx_) {
        err_ = "out of memory";
        return false;
    }
    const uint8_t* base = static_cast<const uint8_t*>(data) + data_off;
    for (int64_t i : ids) {
        const char* nm = gguf_get_tensor_name(gguf_, i);
        ggml_tensor* src = ggml_get_tensor(meta, nm);
        ggml_tensor* t = ggml_new_tensor(ctx_, src->type, GGML_MAX_DIMS, src->ne);
        if (!t) {
            err_ = "out of memory";
            return false;
        }
        ggml_set_name(t, nm + prefix.size());
        std::memcpy(t->data, base + gguf_get_tensor_offset(gguf_, i), ggml_nbytes(t));
    }
    return read_model(prefix);
}

bool ModelLoader::read_model(const std::string& prefix) {
    Kv kv{gguf_, prefix, {}};
    cfg_.arch       = kv.str("ced.arch", "ced");
    cfg_.embed_dim  = kv.u32("ced.embed_dim");
    cfg_.depth      = kv.u32("ced.depth");
    cfg_.num_heads  = kv.u32("ced.num_heads");
    cfg_.outputdim  = kv.u32("ced.outputdim");
    cfg_.mlp_ratio  = kv.f32("ced.mlp_ratio", 4.0f);
    cfg_.qkv_bias   = kv.boolean("ced.qkv_bias", true);
    cfg_.patch_size = kv.u32("ced.patch_size", 16);
    cfg_.patch_stride = kv.u32("ced.patch_stride", 16);
    cfg_.target_length = kv.u32("ced.target_length");
    cfg_.pooling    = kv.str("ced.pooling", "mean");
    cfg_.ln_eps_encoder = kv.f32("ced.ln_eps_encoder", 1e-6f);
    cfg_.ln_eps_head    = kv.f32("ced.ln_eps_head", 1e-5f);
    cfg_.bn_eps         = kv.f32("ced.bn_eps", 1e-5f);
    cfg_.sample_rate = kv.u32("ced.sample_rate", 16000);
    cfg_.n_mels   = kv.u32("ced.n_mels");
    cfg_.n_fft    = kv.u32("ced.n_fft");
    cfg_.win_size = kv.u32("ced.win_size");
    cfg_.hop_size = kv.u32("ced.hop_size");
    cfg_.n_freqs  = kv.u32("ced.n_freqs");
    cfg_.f_min    = kv.f32("ced.f_min", 0.0f);
    cfg_.f_max    = kv.f32("ced.f_max", 8000.0f);
    cfg_.center   = kv.boolean("ced.center", true);
    cfg_.a2db_multiplier = kv.f32("ced.a2db_multiplier", 10.0f);
    cfg_.a2db_amin   = kv.f32("ced.a2db_amin", 1e-10f);
    cfg_.a2db_top_db = kv.f32("ced.a2db_top_db", 120.0f);
    cfg_.a2db_ref    = kv.f32("ced.a2db_ref", 1.0f);
    {
        int64_t id = kv.find("ced.labels", GGUF_TYPE_STRING, /*array=*/true);
        if (id >= 0) {
            size_t n = gguf_get_arr_n(gguf_, id);
            cfg_.labels.resize(n);
            for (size_t i = 0; i < n; ++i) cfg_.labels[i] = gguf_get_arr_str(gguf_, id, i);
        }
    }
    if (!kv.bad.empty()) {
        err_ = kv.bad;
        return false;
    }
    // Every tensor of the context (path loads: the whole file; prefixed loads:
    // the component, names already stripped).
    for (ggml_tensor* t = ggml_get_first_tensor(ctx_); t; t = ggml_get_next_tensor(ctx_, t))
        tensors_[ggml_get_name(t)] = t;
    if (!(cfg_.embed_dim > 0 && cfg_.depth > 0 && cfg_.outputdim > 0)) {
        err_ = "GGUF is not a ced model (missing ced.embed_dim, ced.depth or ced.outputdim)";
        return false;
    }
    return true;
}

ggml_tensor* ModelLoader::tensor(const std::string& n) const {
    auto it = tensors_.find(n);
    return it == tensors_.end() ? nullptr : it->second;
}

